function wordParts(w){let k=w[1].toLowerCase(),p=Object.hasOwn(wordDetails,k)?wordDetails[k][1]:'';let out=[];if(p.includes('существительное'))out.push('noun');if(p.includes('глагол'))out.push('verb');if(p.includes('прилагательное'))out.push('adjective');if(p.includes('наречие'))out.push('adverb');if(p.includes('фразовый глагол'))out.push('phrasal');if(p.includes('предлог'))out.push('preposition');if(p.includes('союз'))out.push('conjunction');if(p.includes('определитель'))out.push('determiner');if(p.includes('междометие'))out.push('interjection');if(p.includes('выражение')&&!p.includes('фразовый глагол'))out.push('expression');return out.length?out:['unknown']}
function matchesCategories(w,topic,pos){let t=Object.hasOwn(wordTopics,w[1].toLowerCase())?wordTopics[w[1].toLowerCase()]:['unknown'];return (topic==='all'||t.includes(topic))&&(pos==='all'||wordParts(w).includes(pos))}
