function openCard(w,random=false){if(openEnglishWord!==w){stopSpeech();$('modal-overlay').querySelector('.modal').scrollTop=0;}openEnglishWord=w;openEnglishRandom=random;$('modal-next-random').classList.toggle('hidden',!random);$('modal-title').textContent='Карточка';let m=$('modal-body');m.replaceChildren(el('div','english-modal-word',w[1]),el('div','modal-meaning',w[2]));if(w[3]||w[4]){let ex=el('div','english-card-example');if(w[3])ex.append(el('p','english-example-en',w[3]),btn('♫','english-inline-audio',()=>speak(w[3])));if(w[4])ex.append(el('p','english-example-ru',w[4]));m.append(ex)}let d=Object.prototype.hasOwnProperty.call(wordDetails,w[1])?wordDetails[w[1]]:null;if(d){let meta=el('div','english-card-meta',w[0]+' · '+d[1]);m.prepend(meta);for(let t of (prefs.transcription==='both'?[d[3],d[0]]:prefs.transcription==='ipa'?[d[3]]:prefs.transcription==='ru'?[d[0]]:[])){if(t)m.insertBefore(el('div','english-card-ipa',t),m.querySelector('.modal-meaning'))}let section=el('div','english-collocations');section.append(el('div','tiny muted','Сочетания и употребление'));for(let phrase of d[2]){let [en,...rest]=phrase.split(' — '),row=el('div','english-collocation');let line=el('div','english-collocation-line');line.append(el('span','',en),btn('♫','english-inline-audio',()=>speak(en)));row.append(line,el('div','english-collocation-ru',rest.join(' — ')));section.append(row)}m.append(section)}let a=el('div','english-actions');a.append(btn('♫ Слушать','soft',()=>speak(w[1])));let s=entry(w);if(s.fav||pendingRemovals.has(removalKey('favorite',w)))a.append(removalButton(w,'favorite','Убрать из избранного','soft'));else a.append(btn('♡ Избранное','soft',()=>{entry(w).fav=true;save();modalDirty=true;openCard(w,random)}));if(s.n>=3||pendingRemovals.has(removalKey('learned',w)))a.append(removalButton(w,'learned','Убрать из изученных','primary'));else a.append(btn('Изучить','primary',()=>{manualToggle(w);modalDirty=true;openCard(w,random)}));if(collection==='due'&&s.due>0&&s.due<=Date.now()&&!hiddenDue.has(w[1]))a.append(removalButton(w,'due','Скрыть до завтра','soft'));if(custom.includes(w))a.append(btn('Редактировать','soft',()=>editWord(w)),btn('Удалить своё слово','ghost',()=>{if(!confirm('Удалить эту карточку?'))return;let next=custom.filter(x=>x!==w);try{localStorage.setItem(customKey,JSON.stringify(next))}catch{alert('Не удалось сохранить изменения');return}discardRemovals(w);custom=next;let builtin=builtinByName.get(w[1].toLowerCase());rebuildVocabulary();forgetPracticeWord(w[1]);if(builtin){if(builtin[1]!==w[1]&&state[w[1]]){if(!state[builtin[1]])state[builtin[1]]=state[w[1]];delete state[w[1]]}}else delete state[w[1]];save();modalDirty=true;$('modal-close').click()}));m.append(a);revealDialog()}
function page(p){if(collection)setCollection(collection);document.querySelector('.hero').classList.toggle('hidden',p!=='learn');window.scrollTo(0,0);for(let x of ['learn','practice','motivation'])$('page-'+x).classList.toggle('hidden',p!==x);document.querySelectorAll('.navbtn').forEach(b=>b.classList.toggle('active',b.dataset.page===p));stopSpeech();if(p!=='practice'){setPracticeFilters(false);setMixedConfig(false)}if(p==='practice')question();else if(p==='motivation'){renderIdiom();renderIdiomCatalog()}else render()}
function normalize(s){return s.toLowerCase().normalize('NFKC').replace(/[’‘]/g,"'").replace(/\b(can't)\b/g,'cannot').replace(/\b(won't)\b/g,'will not').replace(/\b(\w+)n't\b/g,'$1 not').replace(/\b(i'm)\b/g,'i am').replace(/\b(you|we|they)'re\b/g,'$1 are').replace(/\b(i|you|we|they)'ve\b/g,'$1 have').replace(/\b(i|you|he|she|it|we|they)'ll\b/g,'$1 will').replace(/\b(he|she|it)'s\s+(?=not\b)/g,'$1 is ').replace(/[.,!?;:…“”"]/g,'').trim().replace(/\s+/g,' ')}
